if getattr(mibBuilder, 'version', (0, 0, 0)) > (4, 4, 0):
    if mibBuilder.loadTexts: ianaMauMIB.setRevisionsDescriptions(('Added coverage for IEEE Std 802.3cs-2022 (Super-PON 10GBASE-SP1\n                    and 10/2.5GBASE-SP1 PHYs), IEEE Std 802.3db-2022 (100GBASE-SR1,\n                    100GBASE-VR1, 200GBASE-SR2, 200GBASE-VR2, 400GBASE-SR4, and\n                    400GBASE-VR4 PHYs), IEEE Std 802.3ck-2022 (100GBASE-CR1/KR1,\n                    200GBASE-CR2/KR2, and 400GBASE-CR4/KR4 PHYs and associated\n                    Auto-Negotiation capabilities), IEEE Std 802.3da-2026 (10BASE-T1M\n                    PHY), IEEE Std 802.3dk-2026 (100GBASE-BR10, 100GBASE-BR20, and\n                    100GBASE-BR40 PHYs), and IEEE Std 802.3dg-2026 (100BASE-T1L PHY and\n                    associated Auto-Negotiation capability).', 'Added support for IEEE Std 802.3df-2024 (400GBASE-DR4-2, \n                    800GBASE-CR8, 800GBASE-DR8, 800GBASE-DR8-2, 800GBASE-KR8, \n                    800GBASE-R, 800GBASE-SR8, and 800GBASE-VR8PHYs).', 'Added support for IEEE Std 802.3cy-2023 (25GBASE-T1 PHYs).', 'Added coverage for IEEE Std 802.3cz-2023 (entries for \n                     2.5GBASE-AU, 5GBASE-AU, 10GBASE-AU, 25GBASE-AU, and \n                     50GBASE-AU).', 'Added MAU types specified in the IEEE Std 802.3cm-2020, \n                     IEEE Std 802.3ch-2020, IEEE Std 802.3ca-2020, IEEE Std \n                     802.3ct-2021, IEEE Std 802.3cp-2021, and aligned with \n                     IEEE Std 802.3-2022.', 'Added MAU types specified in IEEE Std 802.3cu-2021', 'Added MAU types and associated AutoNeg\n                     capability bits specified in the IEEE Std 802.3-2018, \n                     as well as IEEE Std 802.3cb-2018, IEEE Std 802.3bt-2018, \n                     IEEE Std 802.3cd-2018, IEEE Std 802.3cn-2019, and \n                     IEEE Std 802.3cg-2019', 'Added support for 2.5GBase-T and 5GBase-T media \n                     types.', 'Added new MAU types and associated AutoNeg \n                     capability bits specified in the IEEE 802.3 \n                     amendments IEEE Std 802.3bk-2013, IEEE Std \n                     802.3bj-2014 and IEEE Std 802.3bm-2015, which \n                     are now published in IEEE Std 802.3-2015, as \n                     well as IEEE Std 802.3bw-2015, IEEE Std \n                     802.3by-2016, IEEE Std 802.3bq-2016 and IEEE \n                     Std 802.3bp-2016.', 'Added IANAifJackType 16.', 'Updated contact info.', 'Added MAU types and associated AutoNeg capability \n                     bits specified in amendments to IEEE Std \n                     802.3-2008: IEEE Std 802.3ba-2010 and IEEE Std \n                     802.3bg-2011.', 'Added assignments that will be included in \n                     Clause 14 of IEEE P802.3.1.', 'Initial version of this MIB as published in\n                     RFC 4836.',))
